class stats:
    def __init__(self, name, maxhealth, health, hunger, sanity, doom, atk, luck, speed, accuracy, xp, gold, hitext, wintext, losetext, checkdesc, image ):
        self.maxhealth = maxhealth
        self.health = health
        self.hunger = hunger
        self.sanity = sanity
        self.doom = doom
        self.atk = atk
        self.luck = luck
        self.accuracy = accuracy
        self.xp = xp
        self.gold = gold
        self.speed = speed
        self.hitext = hitext
        self.wintext = wintext
        self.losetext = losetext
        self.checkdesc = checkdesc
        self.name = name
        self.image = image



class protag(stats):
    def __init__(self, inv, mxp, gun):
        self.inv = inv
        self.mxp = mxp
        self.gun = gun
        super().__init__("You", 10, 10, 100, 100, 0, 1, 0, 50, 90, 0, 0, "You attack!", "You won!", "You lost!", "It's you", "I don't have anything here")

