class copycat(stats):
    def hp(self):
        x = player.health
        return x
    def __init__(self):
        super().__init__("You", player.maxhealth, self.hp(), 100, 50, 0, player.atk, player.luck, player.speed, player.accuracy, int(player.xp / 2), player.gold, "You attack!", "Nothing has changed.\nI am still me\nI am the real self", "You are defeated!", "It's you\nIt's not you\nIt's you\nIt's not you", "")





